    ok,
    endToEndProductionComplete,
    marker: IVX_SENIOR_DEVELOPER_RUNTIME_MARKER,
    jobId,
    goal,
    ownerApprovedAction: input.ownerApprovedAction ?? null,
    phases,
    repoBrain,
