    `RENDER_DEPLOY_ID: ${report.RENDER_DEPLOY_ID ?? 'none'}`,
    `LIVE_VERIFY: ${report.LIVE_VERIFY}`,
    `BLOCKERS: ${report.BLOCKERS.length > 0 ? report.BLOCKERS.join('; ') : 'none'}`,
    `NEXT_ACTION: ${report.NEXT_ACTION}`,
  ];
  return lines.join('\n');
}

